        return False
    xs = [int(v) for v in t[1:1 + n]]
    if not all(0 <= x <= 10**8 for x in xs):
        return False
    if any(xs[i] >= xs[i + 1] for i in range(n - 1)):
        return False
    q = int(t[1 + n])
    if not (1 <= q <= 2 * 10**5):
        return False
    rest = t[2 + n:]
    if len(rest) != 2 * q:
        return False
    for i in range(q):
        ti = int(rest[2 * i])
        gi = int(rest[2 * i + 1])
        if not (1 <= ti <= n and 0 <= gi <= 10**8):
